public class ErpCustomerSync {
    private static final Integer CALLS_PER_JOB = 50;

    public class CustomerRecord {
        public String salesforceId;
        public String name;
        public String country;
    }

    public class SyncJob implements Queueable {
        private final List<CustomerRecord> customers;

        public SyncJob(List<CustomerRecord> customers) {
            this.customers = customers;
        }

        public void execute(QueueableContext context) {
            if (customers == null || customers.size() == 0) {
                return;
            }

            for (CustomerRecord customer : customers) {
                sendCustomer(customer);
            }
        }
    }

    public static void enqueueForNewAccounts(List<Account> accounts) {
        if (accounts == null || accounts.size() == 0) {
            return;
        }

        List<CustomerRecord> customers = new List<CustomerRecord>();
        for (Account account : accounts) {
            if (account == null || account.Id == null) {
                continue;
            }

            CustomerRecord record = new CustomerRecord();
            record.salesforceId = account.Id.toString();
            record.name = account.Name;
            record.country = account.BillingCountry;
            customers.add(record);
        }

        if (customers.size() == 0) {
            return;
        }

        for (Integer i = 0; i < customers.size(); i += CALLS_PER_JOB) {
            Integer end = i + CALLS_PER_JOB;
            if (end > customers.size()) {
                end = customers.size();
            }

            List<CustomerRecord> chunk = new List<CustomerRecord>();
            for (Integer j = i; j < end; j++) {
                chunk.add(customers[j]);
            }

            System.enqueueJob(new SyncJob(chunk));
        }
    }

    private static void sendCustomer(CustomerRecord customer) {
        if (customer == null || customer.salesforceId == null || customer.salesforceId.trim().length() == 0) {
            return;
        }

        String idJson = JSON.serialize(customer.salesforceId);
        String nameValue = customer.name == null ? '' : customer.name;
        String nameJson = JSON.serialize(nameValue);

        String countryJson;
        if (customer.country == null || customer.country.trim().length() == 0) {
            countryJson = 'null';
        } else {
            countryJson = JSON.serialize(customer.country);
        }

        String body = '[{"salesforceId":' + idJson + ',"name":' + nameJson + ',"country":' + countryJson + '}]';

        HttpRequest request = new HttpRequest();
        request.setEndpoint('callout:ERP/api/customers');
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setBody(body);
        request.setTimeout(120000);

        new Http().send(request);
    }
}
