public class DealEventPublisher {
    /**
     * Deviation from the literal instruction to call EventBus.publish for each opportunity:
     *
     * One publish/DML statement per opportunity would exceed the 150 DML statement limit
     * when the trigger handler receives 200 opportunities. This class instead publishes
     * all events in one bulk immediate call.
     *
     * allOrNone=false is used so that each event still produces its own SaveResult in the
     * same order as the input list, allowing the caller to identify exactly which event failed.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<SObject> events = new List<SObject>(opportunities.size());

        for (Opportunity opportunity : opportunities) {
            Deal_Stage_Change__e event = new Deal_Stage_Change__e();

            if (opportunity != null) {
                event.Opportunity_Id__c = opportunity.Id;
                event.Stage__c = opportunity.StageName;
                event.Amount__c = opportunity.Amount;
            }

            events.add(event);
        }

        return EventBus.insertImmediate(events, false);
    }
}
