trigger CaseTrigger on Case (after update) {
    List<Id> newlyClosedCaseIds = new List<Id>();

    // Only process cases that change from not closed to closed and have a contact.
    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (oldCase != null && !oldCase.IsClosed && c.IsClosed && c.ContactId != null) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    if (newlyClosedCaseIds.isEmpty()) {
        return;
    }

    // Change from the original "one job per case for every case" approach:
    // a transaction can enqueue at most 50 queueable jobs. Agents and the nightly
    // cleanup can close more than 50 cases in one transaction, so when the number
    // of newly closed cases is greater than 50, we batch case IDs into no more
    // than 50 CaseSurveyJob jobs. Each job still validates the case and creates
    // the task(s) without letting one bad record roll back the others.
    Integer maxQueueablesPerTx = 50;
    Integer minBatchSize = 50;

    if (newlyClosedCaseIds.size() <= maxQueueablesPerTx) {
        // Preserve the requested one-job-per-case behavior when the limit allows it.
        for (Id caseId : newlyClosedCaseIds) {
            System.enqueueJob(new CaseSurveyJob(caseId));
        }
    } else {
        Integer total = newlyClosedCaseIds.size();

        // Choose a batch size that produces no more than maxQueueablesPerTx jobs.
        // For 200 cases this produces 4 jobs of 50 case IDs each.
        Integer batchSize = (total + maxQueueablesPerTx - 1) / maxQueueablesPerTx;
        if (batchSize < minBatchSize) {
            batchSize = minBatchSize;
        }

        for (Integer i = 0; i < total; i += batchSize) {
            Integer end = i + batchSize;
            if (end > total) {
                end = total;
            }

            List<Id> chunk = newlyClosedCaseIds.sublist(i, end);
            System.enqueueJob(new CaseSurveyJob(chunk));
        }
    }
}
