public with sharing class CaseSurveyJob implements Queueable {
    private final List<Id> caseIds;

    // Supports the original single-case usage:
    // System.enqueueJob(new CaseSurveyJob(caseId));
    public CaseSurveyJob(Id caseId) {
        caseIds = new List<Id>();
        if (caseId != null) {
            caseIds.add(caseId);
        }
    }

    // Supports batched usage from the trigger when more than 50 cases are closed
    // in one transaction.
    public CaseSurveyJob(List<Id> ids) {
        caseIds = new List<Id>();
        if (ids != null) {
            for (Id id : ids) {
                if (id != null) {
                    caseIds.add(id);
                }
            }
        }
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        // The trigger normally sends at most 100 IDs per job. This outer loop also
        // keeps the job safe if a very large list is enqueued directly.
        for (Integer i = 0; i < caseIds.size(); i += 5000) {
            Integer end = i + 5000;
            if (end > caseIds.size()) {
                end = caseIds.size();
            }

            List<Id> chunkIds = caseIds.sublist(i, end);

            // Re-query in the async context so we do not rely on trigger state that
            // may have changed before this job runs.
            List<Case> cases = [
                SELECT Id, CaseNumber, ContactId, IsClosed
                FROM Case
                WHERE Id IN :chunkIds
                LIMIT 5000
            ];

            List<Task> tasks = new List<Task>();

            for (Case c : cases) {
                // Cases without a contact get no task.
                // If the case was reopened before this job ran, do not create a task.
                if (c.IsClosed && c.ContactId != null) {
                    tasks.add(new Task(
                        WhatId = c.Id,
                        WhoId = c.ContactId,
                        Subject = 'CSAT survey: ' + c.CaseNumber,
                        ActivityDate = Date.today().addDays(2),
                        Status = 'Not Started'
                    ));
                }
            }

            if (tasks.isEmpty()) {
                continue;
            }

            // Insert in sub-batches with allOrNone = false so that a failure on one
            // task does not prevent the remaining tasks from being created.
            for (Integer j = 0; j < tasks.size(); j += 100) {
                Integer taskEnd = j + 100;
                if (taskEnd > tasks.size()) {
                    taskEnd = tasks.size();
                }

                List<Task> taskChunk = tasks.sublist(j, taskEnd);
                Database.compositeInsert(taskChunk, false);
            }
        }
    }
}
