public class RenewalReminderService {
    /**
     * Sends one renewal reminder email to the owner of each opportunity.
     *
     * Note: Sending up to 200 emails in a single transaction is not a good
     * production pattern because Apex limits Messaging.sendEmail to 10 email
     * invocations per transaction. This method stops when that limit is
     * reached. For production, chunk this work into batch Apex or queueable
     * Apex so each chunk is a separate transaction.
     */
    private static final Integer EMAIL_LIMIT_PER_TRANSACTION = 10;

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, OwnerId, CloseDate
                FROM Opportunity
                WHERE Id IN :uniqueOpportunityIds
            ]
        );

        Integer sentCount = 0;

        for (Id opportunityId : uniqueOpportunityIds) {
            if (Limit.getEmailInvocations() >= EMAIL_LIMIT_PER_TRANSACTION) {
                break;
            }

            Opportunity opportunity = opportunitiesById.get(opportunityId);

            if (
                opportunity == null
                || opportunity.OwnerId == null
                || opportunity.Name == null
                || opportunity.Name.trim().length() == 0
            ) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opportunity.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opportunity.Name);

            String closeDateText = opportunity.CloseDate == null
                ? 'not set'
                : opportunity.CloseDate.format();

            email.setPlainTextBody(
                'Hello,\n\n' +
                'The opportunity ' + opportunity.Name + ' is due for renewal.\n' +
                'Close date: ' + closeDateText + '\n\n' +
                'Please follow up before the close date.\n'
            );

            try {
                List<EmailSendStatus> statuses = Messaging.sendEmail(
                    new List<Messaging.SingleEmailMessage> { email }
                );

                if (statuses != null && statuses.size() > 0 && statuses[0].getIsSuccess()) {
                    sentCount++;
                }
            } catch (Exception ex) {
                // Continue with the next opportunity.
            }
        }

        return sentCount;
    }
}
